{"explanation":"The Inscribed Angle Theorem says that an angle inscribed in a circle (∠ACB) is exactly half the central angle (∠AOB) that subtends the same arc AB. Drag the yellow point C around the circle: as long as C stays on the same arc, the inscribed angle never changes, because the arc it subtends (highlighted in orange) is unchanged. If you drag C past A or B onto the other arc, it subtends the opposite arc and the angle becomes supplementary (the two values add to 180°). You can also drag A or B to change the arc itself and watch the 2:1 relationship update live.","manimCode":"const R = 2.4;
const O = [-1.8, -0.3, 0];
const TAU = Math.PI * 2;

function ptOnCircle(a) {
  return [O[0] + R * Math.cos(a), O[1] + R * Math.sin(a), 0];
}
function angleOf(dot) {
  const p = dot.getCenter();
  return Math.atan2(p[1] - O[1], p[0] - O[0]);
}
function arcInfo() {
  const aA = angleOf(dotA), aB = angleOf(dotB), aC = angleOf(dotC);
  const d = (((aB - aA) % TAU) + TAU) % TAU;
  const dc = (((aC - aA) % TAU) + TAU) % TAU;
  let start, sweep;
  if (dc < d) { start = aB; sweep = TAU - d; } else { start = aA; sweep = d; }
  return { start: start, sweep: sweep, inscribed: sweep / 2 };
}
function circleArcVerts(radius, start, sweep) {
  const n = Math.max(14, Math.ceil(sweep * 26));
  const v = [];
  for (let i = 0; i <= n; i++) {
    const a = start + sweep * (i / n);
    v.push([O[0] + radius * Math.cos(a), O[1] + radius * Math.sin(a), 0]);
  }
  return v;
}
function inscribedArcVerts() {
  const c = dotC.getCenter(), pa = dotA.getCenter(), pb = dotB.getCenter();
  const a1 = Math.atan2(pa[1] - c[1], pa[0] - c[0]);
  const a2 = Math.atan2(pb[1] - c[1], pb[0] - c[0]);
  const delta = ((((a2 - a1 + Math.PI) % TAU) + TAU) % TAU) - Math.PI;
  const n = 22, r = 0.5, v = [];
  for (let i = 0; i <= n; i++) {
    const ang = a1 + delta * (i / n);
    v.push([c[0] + r * Math.cos(ang), c[1] + r * Math.sin(ang), 0]);
  }
  return v;
}
function openLine(verts) {
  return verts.concat(verts.slice(0, -1).reverse());
}

const circle = new Circle({ radius: R, color: WHITE });
circle.moveTo(O);
circle.setFillOpacity(0);
circle.setStrokeWidth(2.5);
const dotO = new Dot({ point: [O[0], O[1], 0], color: WHITE });

const dotA = new Dot({ point: ptOnCircle(200 * Math.PI / 180), color: TEAL });
const dotB = new Dot({ point: ptOnCircle(340 * Math.PI / 180), color: TEAL });
const dotC = new Dot({ point: ptOnCircle(90 * Math.PI / 180), color: YELLOW });

const chordCA = new Polygon({ vertices: [dotC.getCenter(), dotA.getCenter()], color: YELLOW });
chordCA.setStrokeWidth(3).setFillOpacity(0);
const chordCB = new Polygon({ vertices: [dotC.getCenter(), dotB.getCenter()], color: YELLOW });
chordCB.setStrokeWidth(3).setFillOpacity(0);
const radOA = new Polygon({ vertices: [[O[0], O[1], 0], dotA.getCenter()], color: ORANGE });
radOA.setStrokeWidth(2.5).setFillOpacity(0);
const radOB = new Polygon({ vertices: [[O[0], O[1], 0], dotB.getCenter()], color: ORANGE });
radOB.setStrokeWidth(2.5).setFillOpacity(0);

const info0 = arcInfo();
const subArc = new Polygon({ vertices: openLine(circleArcVerts(R, info0.start, info0.sweep)), color: ORANGE });
subArc.setStrokeWidth(7).setFillOpacity(0);
const cenArc = new Polygon({ vertices: openLine(circleArcVerts(0.55, info0.start, info0.sweep)), color: ORANGE });
cenArc.setStrokeWidth(4).setFillOpacity(0);
const insArc = new Polygon({ vertices: openLine(inscribedArcVerts()), color: YELLOW });
insArc.setStrokeWidth(4).setFillOpacity(0);

chordCA.addUpdater(() => chordCA.setVertices([dotC.getCenter(), dotA.getCenter()]));
chordCB.addUpdater(() => chordCB.setVertices([dotC.getCenter(), dotB.getCenter()]));
radOA.addUpdater(() => radOA.setVertices([[O[0], O[1], 0], dotA.getCenter()]));
radOB.addUpdater(() => radOB.setVertices([[O[0], O[1], 0], dotB.getCenter()]));
subArc.addUpdater(() => { const i = arcInfo(); subArc.setVertices(openLine(circleArcVerts(R, i.start, i.sweep))); });
cenArc.addUpdater(() => { const i = arcInfo(); cenArc.setVertices(openLine(circleArcVerts(0.55, i.start, i.sweep))); });
insArc.addUpdater(() => insArc.setVertices(openLine(inscribedArcVerts())));

const labelA = new Text({ text: 'A', color: TEAL, fontSize: 26 });
const labelB = new Text({ text: 'B', color: TEAL, fontSize: 26 });
const labelC = new Text({ text: 'C', color: YELLOW, fontSize: 26 });
function placeLabel(label, dot) {
  const p = dot.getCenter();
  const dx = p[0] - O[0], dy = p[1] - O[1];
  const l = Math.hypot(dx, dy) || 1;
  label.moveTo([p[0] + 0.42 * dx / l, p[1] + 0.42 * dy / l, 0]);
}
labelA.addUpdater(() => placeLabel(labelA, dotA));
labelB.addUpdater(() => placeLabel(labelB, dotB));
labelC.addUpdater(() => placeLabel(labelC, dotC));
const labelO = new Text({ text: 'O', color: WHITE, fontSize: 22 });
labelO.moveTo([O[0] - 0.3, O[1] - 0.35, 0]);

let inscText = null, centText = null;
function updateReadout() {
  const i = arcInfo();
  const deg = i.inscribed * 180 / Math.PI;
  const cdeg = i.sweep * 180 / Math.PI;
  if (inscText) scene.remove(inscText);
  inscText = new Text({ text: 'Inscribed angle = ' + deg.toFixed(1) + '\u00B0', color: YELLOW, fontSize: 28 });
  inscText.moveTo([3.6, 1.35, 0]);
  scene.add(inscText);
  if (centText) scene.remove(centText);
  centText = new Text({ text: 'Central angle = ' + cdeg.toFixed(1) + '\u00B0', color: ORANGE, fontSize: 28 });
  centText.moveTo([3.6, 0.65, 0]);
  scene.add(centText);
}

const title = new Text({ text: 'Inscribed Angle Theorem', color: WHITE, fontSize: 38 });
title.moveTo([0, 3.3, 0]);
const formula = new MathTex({ latex: '\\angle ACB = \\frac{1}{2}\\, \\angle AOB' });
await formula.waitForRender();
formula.moveTo([3.6, -0.6, 0]);
const caption = new Text({ text: '(central angle on the highlighted arc)', color: GRAY, fontSize: 18 });
caption.moveTo([3.6, -1.25, 0]);
const hint = new Text({ text: 'Drag C around the circle \u2014 the angle stays constant on the same arc. Drag A or B to change the arc.', color: GRAY, fontSize: 20 });
hint.moveTo([0, -3.5, 0]);

scene.add(circle, subArc, radOA, radOB, chordCA, chordCB, cenArc, insArc, dotO, dotA, dotB, dotC, labelA, labelB, labelC, labelO, title, formula, caption, hint);
updateReadout();

function dragOnCircle(mob) {
  const p = mob.getCenter();
  const dx = p[0] - O[0], dy = p[1] - O[1];
  const l = Math.hypot(dx, dy) || 1;
  mob.moveTo([O[0] + R * dx / l, O[1] + R * dy / l, 0]);
  updateReadout();
}
makeDraggable(dotA, scene, { onDrag: dragOnCircle });
makeDraggable(dotB, scene, { onDrag: dragOnCircle });
makeDraggable(dotC, scene, { onDrag: dragOnCircle });
makeHoverable(dotA, scene, { hoverScale: 1.5, cursor: 'grab' });
makeHoverable(dotB, scene, { hoverScale: 1.5, cursor: 'grab' });
makeHoverable(dotC, scene, { hoverScale: 1.5, cursor: 'grab' });

await scene.wait(999999);"}

